 "course-src/tests/21.09.test.js": "import{somaComReduce,somaComFor,medir}from'./lab.js';test('sum equivalence and finite-input rejection',()=>{for(const xs of [[],[1,2,3],[-2,10]])/*@case 21.09.sum-equivalence-and-finite-i-4444a7f8*/expect(somaComReduce(xs)).toBe(somaComFor(xs));/*@case 21.09.sum-equivalence-and-finite-i-bd28b01d*/expect(()=>medir(somaComFor,[1,Infinity])).toThrow(TypeError);});test('report has fixed sample count and null when memory absent',()=>{let t=0;const r=medir(()=>{},[1],{runs:3,warmups:0,now:()=>t++});/*@case 21.09.report-has-fixed-sample-coun-bd533a3a*/expect(r.samples.length).toBe(3);/*@case 21.09.report-has-fixed-sample-coun-71f8f92d*/expect(r.min<=r.max).toBe(true);});\n",
 "course-src/tests/21.13.test.js": "import {criarContador, ouvirAte} from './main.js';\r\n\r\ndescribe('contador com eventos', () => {\r\n  test('emite o novo valor a cada incremento', () => {\r\n    const contador = criarContador();\r\n    const valores = [];\r\n    contador.addEventListener('mudou', evento => valores.push(evento.detail.valor));\r\n    contador.incrementar();\r\n    contador.incrementar();\r\n    /*@case 21.13.emite-o-novo-valor-a-cada-in-511c7c6e*/expect(valores).toEqual([1, 2]);\r\n    /*@case 21.13.emite-o-novo-valor-a-cada-in-ded6c3e8*/expect(contador.valor).toBe(2);\r\n  });\r\n});\r\n\r\ndescribe('escuta cancelável', () => {\r\n  test('para de receber eventos depois que o sinal é abortado', () => {\r\n    const contador = criarContador();\r\n    const controle = new AbortController();\r\n    let chamadas = 0;\r\n    ouvirAte(contador, () => { chamadas += 1; }, controle.signal);\r\n    contador.incrementar();\r\n    controle.abort();\r\n    contador.incrementar();\r\n    /*@case 21.13.para-de-receber-eventos-depo-78b1700b*/expect(chamadas).toBe(1);\r\n  });\r\n});\r\n",
