 "course-src/tests/22.04.test.js": "import{first,migrar}from'./patch.js';test('module helper returns first and empty undefined',()=>{/*@case 22.04.module-helper-returns-first--455b7d3f*/expect(first([4,5])).toBe(4);/*@case 22.04.module-helper-returns-first--11be7f5f*/expect(first([])).toBe(undefined);/*@case 22.04.module-helper-returns-first--9c996747*/expect(migrar([8])).toBe(8);});test('prototype and enumeration remain clean',()=>{/*@case 22.04.prototype-and-enumeration-re-9556e15e*/expect(Object.hasOwn(Array.prototype,'first')).toBe(false);const keys=[];for(const k in [])keys.push(k);/*@case 22.04.prototype-and-enumeration-re-48e54806*/expect(keys).toEqual([]);});\n",
